// Text for the console (renderTable) and the markdown report (renderReport).
// The report is generated: do not edit docs/agents/ws1-eval-report.md by hand.

import { BEHAVIORS } from '../../../src/storage/eventModel.ts';
import { BEHAVIOR_REGISTRY } from '../../../src/detection/registry.ts';
import { SENSITIVITIES } from './evaluate.mjs';

const pct = v => (v === null ? 'n/a' : v.toFixed(2));

function counts(fixtures) {
  const real = fixtures.filter(f => f.source === 'real').length;
  return { total: fixtures.length, real, synthetic: fixtures.length - real };
}

function statusOf(row, isGate, gateName = 'the gate sensitivity') {
  if (!row.gated) {
    const where = row.passesBar ? 'meets its bar on synthetic scenes' : 'below its bar';
    return `experimental, ${where}${row.promotable ? ', real fixtures meet it: can be promoted' : `, cannot be promoted (${row.realEvents} real events)`}`;
  }
  if (!isGate) return `validated (the bar is judged at ${gateName})`;
  return row.passesBar ? 'validated, PASS' : 'validated, FAIL';
}

function pad(s, n) { return String(s).padEnd(n); }

export function renderTable({ fixtures, thresholds, bySensitivity, verdict }) {
  const c = counts(fixtures);
  const lines = [];
  lines.push(`Detection evaluation: ${c.total} fixtures (${c.synthetic} synthetic, ${c.real} real).`);
  if (c.real === 0) lines.push('ALL FIXTURES ARE SYNTHETIC. These numbers are a regression guard, not real-world accuracy.');
  for (const s of SENSITIVITIES) {
    const isGate = s === thresholds.gateSensitivity;
    lines.push('', `Sensitivity ${s}${isGate ? '  (gate)' : ''}`);
    lines.push(`${pad('rule', 22)}${pad('level', 14)}${pad('precision', 11)}${pad('recall', 8)}${pad('alarms ok/false', 17)}${pad('events found', 14)}${pad('bar P/R', 11)}status`);
    for (const row of bySensitivity[s]) {
      lines.push(
        pad(row.behavior, 22) + pad(row.level, 14) + pad(pct(row.precision), 11) + pad(pct(row.recall), 8)
        + pad(`${row.correct}/${row.falseAlarms}`, 17) + pad(`${row.detected}/${row.events}`, 14)
        + pad(`${row.bar.minPrecision}/${row.bar.minRecall}`, 11) + statusOf(row, isGate, thresholds.gateSensitivity),
      );
    }
  }
  lines.push('', verdict.ok ? 'OK: every validated rule meets its bar.' : 'FAILED: a validated rule is below its bar.');
  return lines.join('\n');
}

function cell(entry) {
  const parts = [];
  if (entry.correct > 0) parts.push(`${entry.correct} ok`);
  if (entry.falseAlarms > 0) parts.push(`${entry.falseAlarms} FALSE`);
  if (entry.events > entry.detected) parts.push(`MISSED ${entry.events - entry.detected}`);
  return parts.length === 0 ? '.' : parts.join(' ');
}

export function renderReport({ fixtures, thresholds, bySensitivity, verdict }) {
  const c = counts(fixtures);
  const gateRows = bySensitivity[thresholds.gateSensitivity];
  const out = [];
  const w = line => out.push(line);

  w('# WS1 detection evaluation report');
  w('');
  w('> **SYNTHETIC. This is not real-world accuracy.**');
  w(`> Every number below comes from ${c.synthetic} landmark fixtures drawn by the same person who wrote the rules (a neutral stick-model face and hand, `
    + 'generated by `scripts/eval-detection/generate-fixtures.mjs`)'
    + (c.real > 0 ? `, plus ${c.real} real recording(s)` : '. No real footage has been tried')
    + '. A high precision here means the rule does what its author imagined on scenes its author drew. '
    + 'It is a guard against regressions and a place to start, nothing more. Do not quote it on the website or anywhere else.');
  w('');
  w('Generated by `npm run eval:detection -- --report docs/agents/ws1-eval-report.md`. Do not edit by hand; regenerate it.');
  w('');
  w('## What was measured');
  w('');
  w(`- ${c.total} fixtures, played at 5 frames per second through the app's own engine (\`src/detection/engine.ts\`), **one rule at a time**, at each of the three sensitivities.`);
  w('- **Alarm**: what a person would hear (one per episode). **Event**: a labelled interval in a fixture that a rule is meant to find.');
  w(`- An alarm is *correct* if it starts inside an event the rule is meant to find (up to ${thresholds.graceMs ?? 1000} ms after it ends), otherwise it is a *false alarm*. `
    + 'An event is *found* if at least one correct alarm falls in it.');
  w('- **Precision** = correct alarms / all alarms. **Recall** = events found / all events. `n/a` means there was nothing to divide by.');
  w('- A fixture can count against a rule it was not drawn for: a fingertip at the nose also sits inside the mouth rule\'s reach, so a nose-picking scene is a false alarm for nail biting. '
    + 'That is real behaviour of the shipped rule, not a bug in the report.');
  w('- Recall is flattering: every positive scene is a long, clean hold with a hand that is tracked perfectly. Real footage has dropped detections, fingers hidden behind each other, motion blur and partial hands, none of which these fixtures contain.');
  w(`- The gate is **${thresholds.gateSensitivity}** sensitivity, the default. A rule marked \`validated\` in \`src/detection/registry.ts\` must meet its bar in \`scripts/eval-detection/thresholds.json\` or the command exits 1. Experimental rules are reported, never gated.`);
  w('');
  w(`## Result at ${thresholds.gateSensitivity} sensitivity (the gate)`);
  w('');
  w('| Rule | Level | Precision | Recall | Alarms (ok / false) | Events (found / all) | Bar (P / R) | Status |');
  w('|---|---|---|---|---|---|---|---|');
  for (const r of gateRows) {
    w(`| \`${r.behavior}\` | ${r.level} | ${pct(r.precision)} | ${pct(r.recall)} | ${r.correct} / ${r.falseAlarms} | ${r.detected} / ${r.events} | ${r.bar.minPrecision} / ${r.bar.minRecall} | ${statusOf(r, true)} |`);
  }
  w('');
  w('Over **all** fixtures, including scenes drawn for other behaviours. The same rules counted only on the scenes drawn for their own behaviour (plus the idle scene):');
  w('');
  w('| Rule | Precision | Recall | Alarms (ok / false) | Events (found / all) |');
  w('|---|---|---|---|---|');
  for (const r of gateRows) {
    w(`| \`${r.behavior}\` | ${pct(r.own.precision)} | ${pct(r.own.recall)} | ${r.own.correct} / ${r.own.falseAlarms} | ${r.own.detected} / ${r.own.events} |`);
  }
  w('');
  w(verdict.ok ? '**Gate: every validated rule meets its bar.**' : `**Gate: FAILED.** ${verdict.failures.join('; ')}`);
  w('');
  w('"Validated" here means: the rule is the one that has shipped, unchanged, and it holds its numbers on these synthetic fixtures. '
    + 'It does **not** mean it was measured on real people. Nothing else is validated, and the experimental rules\' bars are the owner\'s promotion targets (see the README): '
    + 'a rule is promoted only after real fixtures meet them.');
  w('');
  w('## All sensitivities');
  w('');
  w('| Rule | ' + SENSITIVITIES.map(s => `${s} P / R (alarms ok-false)`).join(' | ') + ' |');
  w('|---|' + SENSITIVITIES.map(() => '---').join('|') + '|');
  for (const b of BEHAVIORS) {
    const cells = SENSITIVITIES.map(s => {
      const r = bySensitivity[s].find(x => x.behavior === b);
      return `${pct(r.precision)} / ${pct(r.recall)} (${r.correct}-${r.falseAlarms})`;
    });
    w(`| \`${b}\` | ${cells.join(' | ')} |`);
  }
  w('');
  w(`## Fixture by fixture (${thresholds.gateSensitivity})`);
  w('');
  w('`ok` = correct alarms, `FALSE` = false alarms, `MISSED` = events no correct alarm fell in, `.` = nothing to report.');
  w('');
  w('| Fixture | Events | ' + BEHAVIORS.map(b => `\`${b}\``).join(' | ') + ' |');
  w('|---|---|' + BEHAVIORS.map(() => '---').join('|') + '|');
  for (const f of fixtures) {
    const events = f.labels.length === 0 ? 'none' : f.labels.map(l => `${l.behaviors[0] === 'nail_biting' ? 'mouth' : l.behaviors[0]} ${(l.startMs / 1000).toFixed(1)}-${(l.endMs / 1000).toFixed(1)} s`).join(', ');
    const cells = BEHAVIORS.map(b => cell(gateRows.find(r => r.behavior === b).perFixture.find(p => p.id === f.id)));
    w(`| \`${f.id}\`${f.source === 'real' ? ' (real)' : ''} | ${events} | ${cells.join(' | ')} |`);
  }
  w('');
  const issues = fixtures.filter(f => f.knownIssue);
  if (issues.length > 0) {
    w('## Known weak spots (drawn on purpose)');
    w('');
    for (const f of issues) w(`- \`${f.id}\`: ${f.knownIssue}`);
    w('');
  }
  w('## Rules and their level');
  w('');
  w('| Behavior | Level | Rule |');
  w('|---|---|---|');
  for (const b of BEHAVIORS) {
    const info = BEHAVIOR_REGISTRY[b];
    w(`| \`${b}\` | ${info.validation} | ${info.rule.zone} zone, ${info.rule.dwellMs} ms, fingers ${info.rule.fingerFilter.join('/')}${info.rule.gesture ? `, ${info.rule.gesture.kind}` : ''} |`);
  }
  w('');
  return out.join('\n');
}
